import anthropic
client = anthropic.Anthropic()

# Extended thinking for hard problems (uses more tokens but much more accurate)
response = client.messages.create(
    model="claude-opus-4-5",
    max_tokens=16000,
    thinking={
        "type": "enabled",
        "budget_tokens": 10000  # tokens allocated for private reasoning
    },
    messages=[{"role": "user", "content":
        """A cryptarithmetic puzzle:
SEND + MORE = MONEY
Each letter represents a unique digit 0-9. Solve for all digits."""
    }]
)

for block in response.content:
    if block.type == "thinking":
        print(f"Thinking ({len(block.thinking)} chars)...")
    elif block.type == "text":
        print("Answer:", block.text)
